use std::collections::HashMap;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Exp {
    Const(i64),
    Var(String),
    Plus(Box<Exp>, Box<Exp>),
    Mult(Box<Exp>, Box<Exp>),
}

impl Exp {
    /// Evaluate the expression `self` under the given `store`.
    /// Variables not found in `store` yield -1.
    pub fn eval(&self, store: &HashMap<String, i64>) -> i64 {
        match self {
            Exp::Const(n) => *n,
            Exp::Var(name) => *store.get(name).unwrap_or(&-1),
            Exp::Plus(l, r) => l.eval(store) + r.eval(store),
            Exp::Mult(l, r) => l.eval(store) * r.eval(store),
        }
    }

    /// Perform a single‐step root‐only peephole optimization.
    /// Does not recurse into subexpressions.
    pub fn optimize(self) -> Exp {
        match self {
            Exp::Mult(left, right) => {
                // Take ownership of the two operands
                let l = *left;
                let r = *right;
                match (l, r) {
                    // absorbing element
                    (Exp::Const(0), _) | (_, Exp::Const(0)) => Exp::Const(0),
                    // neutral element
                    (Exp::Const(1), rhs) => rhs,
                    (lhs, Exp::Const(1)) => lhs,
                    // constant folding
                    (Exp::Const(a), Exp::Const(b)) => Exp::Const(a * b),
                    // otherwise rebuild the same tree
                    (lhs, rhs) => Exp::Mult(Box::new(lhs), Box::new(rhs)),
                }
            }
            Exp::Plus(left, right) => {
                let l = *left;
                let r = *right;
                match (l, r) {
                    // neutral element
                    (Exp::Const(0), rhs) => rhs,
                    (lhs, Exp::Const(0)) => lhs,
                    // constant folding
                    (Exp::Const(a), Exp::Const(b)) => Exp::Const(a + b),
                    // otherwise rebuild
                    (lhs, rhs) => Exp::Plus(Box::new(lhs), Box::new(rhs)),
                }
            }
            // Constants and variables remain unchanged
            Exp::Const(n) => Exp::Const(n),
            Exp::Var(name) => Exp::Var(name),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_eval_and_optimize() {
        let mut store = HashMap::new();
        store.insert("x".to_string(), 7);
        store.insert("y".to_string(), 3);

        // (x * 1) + (0 * y)  --> should optimize to  x + 0  --> then to x
        let expr = Exp::Plus(
            Box::new(Exp::Mult(
                Box::new(Exp::Var("x".into())),
                Box::new(Exp::Const(1)),
            )),
            Box::new(Exp::Mult(
                Box::new(Exp::Const(0)),
                Box::new(Exp::Var("y".into())),
            )),
        );

        // Single‐step optimize at top will only see the outer Plus:
        // It's not (Const(0) + _), nor (_ + Const(0)), nor two Consts,
        // so it leaves the Plus node in place.
        let opt1 = expr.clone().optimize();
        assert_eq!(opt1, expr);

        // If we manually rewrite deeper, for testing:
        let left = Exp::Mult(
            Box::new(Exp::Var("x".into())),
            Box::new(Exp::Const(1)),
        )
        .optimize(); // == Var("x")
        let right = Exp::Mult(
            Box::new(Exp::Const(0)),
            Box::new(Exp::Var("y".into())),
        )
        .optimize(); // == Const(0)
        let expr2 = Exp::Plus(Box::new(left), Box::new(right)).optimize(); // == left == Var("x")

        assert_eq!(expr2, Exp::Var("x".into()));
        assert_eq!(expr2.eval(&store), 7);

        // Check that eval(original) == eval(fully optimized)
        assert_eq!(expr.eval(&store), 7);
        assert_eq!(expr2.eval(&store), 7);
    }
}